import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, fix an integer base c = {base_c} with c > 1. Define A = c^{exp_m} and B = c^{exp_n}, where exp_m and exp_n are distinct positive integers. Consider the system of equations:\n  log_A x + log_B y = {sum_s}\n  log_x A - log_y B = {diff_t}\nThis system has exactly two real solutions (x1, y1) and (x2, y2) with x1, x2, y1, y2 > 0 and each logarithm well-defined (all bases positive and not equal to 1). Compute the value of log_{c^{base_r}}(x1 y1 x2 y2).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generates parameters for the harder generalization.
# We use u=1, v=-1 so the second equation is 1/a - 1/b = T after change-of-base.
def divisors(n):
    n = abs(n)
    ds = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            ds.add(i)
            ds.add(n // i)
    return sorted(ds)
for _ in range(500):
    base_c = rng.randint(2, 12)
    exp_m = rng.randint(1, 8)
    # choose exp_n distinct from exp_m
    candidates = [k for k in range(1, 9) if k != exp_m]
    rng.shuffle(candidates)
    if not candidates:
        continue
    exp_n = candidates[0]
    diff = exp_n - exp_m
    # ensure a nontrivial skew: T divides 2*diff, T >= 2
    T_divs = [d for d in divisors(2 * abs(diff)) if d >= 2]
    if not T_divs:
        continue
    diff_t = rng.choice(T_divs)
    sum_s = rng.randint(2, 12)
    # N is the numerator of the final answer before dividing by r
    # N = S*(m+n) - 2*(n - m)/T
    N_num = sum_s * (exp_m + exp_n) - (2 * diff) // diff_t
    # enforce positivity and nontriviality
    if N_num <= 0:
        continue
    # choose r as a nontrivial divisor (>=2) of N_num, and keep it moderate
    N_divs = [d for d in divisors(N_num) if 2 <= d <= 12]
    if not N_divs:
        continue
    base_r = rng.choice(N_divs)
    # Optional sanity: keep c^r reasonably sized implicitly by r<=12
    return {
        'base_c': base_c,
        'exp_m': exp_m,
        'exp_n': exp_n,
        'sum_s': sum_s,
        'diff_t': diff_t,
        'base_r': base_r
    }
# Fallback deterministic assignment if randomness fails (rare)
return {
    'base_c': 2,
    'exp_m': 3,
    'exp_n': 5,
    'sum_s': 4,
    'diff_t': 2,
    'base_r': 2
}

    def verifier(assign):
# Verify parameters and compute the answer using the derived closed form.
# Domain checks and difficulty guards included.
try:
    base_c = int(assign['base_c'])
    exp_m = int(assign['exp_m'])
    exp_n = int(assign['exp_n'])
    sum_s = int(assign['sum_s'])
    diff_t = int(assign['diff_t'])
    base_r = int(assign['base_r'])
except Exception:
    # Missing or non-integer slots
    return (False, None)
# Basic domain checks
if not (base_c > 1 and exp_m > 0 and exp_n > 0 and exp_m != exp_n and sum_s > 0 and diff_t >= 2 and base_r >= 2):
    # Require diff_t>=2 and base_r>=2 to avoid trivialities and ensure harder-than-seed nature
    return (False, None)
# Ensure integrality constraint used by generator (for the final expression): diff_t divides 2*(exp_n-exp_m)
if (2 * (exp_n - exp_m)) % diff_t != 0:
    # This guarantees the numerator is integer
    return (False, None)
# Compute A, B for internal consistency (not used in final but for discriminant check)
A = base_c ** exp_m
B = base_c ** exp_n
if not (A > 1 and B > 1):
    return (False, None)
# Discriminant for the quadratic in a = log_A x: T a^2 + ((v - u) - T S) a + u S = 0 with u=1, v=-1
# Coeffs: T, ((-2) - T S), S
T = diff_t
S = sum_s
disc = ((-2) - T * S) ** 2 - 4 * T * S
# Disc is strictly positive for T>=1 and S>0, but we still check
if not (disc > 0):
    return (False, None)
# Final answer: log_{c^r}(x1 y1 x2 y2) = [S(m+n) - 2(n - m)/T] / r
numerator = S * (exp_m + exp_n) - (2 * (exp_n - exp_m)) // T
# Enforce nontriviality and divisibility by r
if numerator <= 0:
    return (False, None)
if numerator % base_r != 0:
    return (False, None)
answer = numerator // base_r
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

